from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message

class OutOfScopeResponse(Component):
    display_name = "OutofScope"
    inputs = [MessageTextInput(name="trigger", display_name="Trigger", required=False)]
    outputs = [Output(display_name="Message", name="message", method="respond")]

    def respond(self) -> Message:
        return Message(text="Mira only handles the ABCDE Ltd. AI Adoption Project — try asking about the project plan, risks, or status.")
